// Web search is rendered per role, from the user's own config.
//
// A role declares web search in its descriptor (role.json `web_search`, generated by
// scripts/derive-roles.mjs). With the installer's VBCDX_AGENTS_HERMES_WEB_SEARCH_URL and
// _TOOL set, the Hermes renderer gives exactly those roles the web-litellm-search plugin,
// plugins.enabled, web.search_backend/extract_backend and the web toolset. There is no
// default gateway: with no config, nothing changes, and a half-set config is an error.
import { test, after } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, writeFileSync, readFileSync, rmSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";
import { parse as yamlParse } from "yaml";
import { getRole } from "../src/roles/index.js";
import {
  renderHermes, renderHermesWebSearchPlugin, HERMES_WEB_SEARCH_PLUGIN, HERMES_WEB_SEARCH_BACKEND,
} from "../src/renderers/hermes.js";
import { hermesToolsets, HERMES_PLATFORMS } from "../src/renderers/native.js";
import { loadConfig, loadHermesWebSearch } from "../src/config/config.js";
import { parseInitArgs } from "../src/cli/args.js";
import { buildPlan } from "../src/planner.js";
import { init } from "../src/index.js";
import { EXIT } from "../src/errors.js";
import { parsePy, stringifyPy } from "../src/fs/pyyaml.js";
import { FIXTURE_IDS, PACK_ARG } from "./helpers/fixture-pack.js";

const cfg = (obj) => new Map(Object.entries(obj));
const files = (out) => Object.fromEntries(out.files.map((f) => [f.name, f.content]));
const SEARCH = { baseUrl: "https://llm.example.com", tool: "example-search" };
const PLUGIN_FILES = [`plugins/${HERMES_WEB_SEARCH_PLUGIN}/plugin.yaml`, `plugins/${HERMES_WEB_SEARCH_PLUGIN}/__init__.py`];
// The roles the descriptor table gives web search: the ones that must check a claim against a source.
const SEARCH_ROLES = ["adversarial-auditor", "pm-agent", "review-agent", "security-agent"];

const roots = [];
after(() => { for (const r of roots) rmSync(r, { recursive: true, force: true }); });

// ── the descriptor ──────────────────────────────────────────────────────────

test("every descriptor states web_search, and exactly the four source-checking roles have it", () => {
  for (const id of FIXTURE_IDS) {
    assert.equal(typeof getRole(id).descriptor.web_search, "boolean", `${id}: web_search is stated`);
  }
  assert.deepEqual(FIXTURE_IDS.filter((id) => getRole(id).descriptor.web_search).sort(), SEARCH_ROLES);
});

// ── the installer config ────────────────────────────────────────────────────

test("web search config: both keys or neither, an http(s) URL without credentials, a plain tool name", () => {
  assert.equal(loadHermesWebSearch(cfg({})), null);
  assert.deepEqual(loadHermesWebSearch(cfg({
    VBCDX_AGENTS_HERMES_WEB_SEARCH_URL: "https://llm.example.com", VBCDX_AGENTS_HERMES_WEB_SEARCH_TOOL: "example-search",
  })), SEARCH);
  // A missing gateway URL is a clear error, never a default host.
  assert.throws(() => loadHermesWebSearch(cfg({ VBCDX_AGENTS_HERMES_WEB_SEARCH_TOOL: "example-search" })),
    /VBCDX_AGENTS_HERMES_WEB_SEARCH_TOOL requires VBCDX_AGENTS_HERMES_WEB_SEARCH_URL \(the LiteLLM gateway URL\)/);
  assert.throws(() => loadHermesWebSearch(cfg({ VBCDX_AGENTS_HERMES_WEB_SEARCH_URL: "https://llm.example.com" })),
    /VBCDX_AGENTS_HERMES_WEB_SEARCH_URL requires VBCDX_AGENTS_HERMES_WEB_SEARCH_TOOL/);
  const both = (url, tool) => cfg({ VBCDX_AGENTS_HERMES_WEB_SEARCH_URL: url, VBCDX_AGENTS_HERMES_WEB_SEARCH_TOOL: tool });
  assert.throws(() => loadHermesWebSearch(both("llm.example.com", "t")), /absolute HTTP\(S\) URL/);
  assert.throws(() => loadHermesWebSearch(both("ftp://llm.example.com", "t")), /http or https/);
  assert.throws(() => loadHermesWebSearch(both("https://u:p@llm.example.com", "t")), /embed credentials/);
  for (const bad of ["a/b", "../x", "a b", "-x", "x?y", 'x"y']) {
    assert.throws(() => loadHermesWebSearch(both("https://llm.example.com", bad)), /not a valid search tool name/, bad);
  }
});

test("loadConfig reads web search for the hermes harness only, and still rejects a misspelt key", () => {
  const base = { VBCDX_AGENTS_BASE_DIR: "/b", VBCDX_AGENTS_CREDENTIALS_DIR: "/c", VBCDX_AGENTS_HERMES_HOME: "/h",
    VBCDX_AGENTS_CLAUDE_CONFIG_DIR: "/cc" };
  const keys = { VBCDX_AGENTS_HERMES_WEB_SEARCH_URL: SEARCH.baseUrl, VBCDX_AGENTS_HERMES_WEB_SEARCH_TOOL: SEARCH.tool };
  assert.deepEqual(loadConfig(cfg({ ...base, ...keys }), { harness: "hermes", scope: "user" }).hermesWebSearch, SEARCH);
  assert.equal(loadConfig(cfg(base), { harness: "hermes", scope: "user" }).hermesWebSearch, null);
  assert.equal(loadConfig(cfg({ ...base, ...keys }), { harness: "claude", scope: "user" }).hermesWebSearch, null);
  assert.throws(() => loadConfig(cfg({ ...base, VBCDX_AGENTS_HERMES_WEB_SEARCH_URLS: "x" }), { harness: "hermes", scope: "user" }),
    /Unsupported configuration key VBCDX_AGENTS_HERMES_WEB_SEARCH_URLS/);
});

test(".env.example documents both keys with example.com values", () => {
  const env = readFileSync(new URL("../.env.example", import.meta.url), "utf8");
  assert.match(env, /^# VBCDX_AGENTS_HERMES_WEB_SEARCH_URL=https:\/\/[\w.-]*example\.com$/m);
  assert.match(env, /^# VBCDX_AGENTS_HERMES_WEB_SEARCH_TOOL=\S+$/m);
});

// ── the render: every role, with and without web search configured ─────────

test("role x web search: a declaring role gets the plugin and config; every other role renders as without it", () => {
  for (const id of FIXTURE_IDS) {
    const role = getRole(id);
    const plain = files(renderHermes(role));
    const withSearch = files(renderHermes(role, { webSearch: SEARCH }));
    if (!SEARCH_ROLES.includes(id)) {
      // Least privilege: not one byte of any file differs, and no plugin is written.
      assert.deepEqual(withSearch, plain, `${id}: unchanged by web search config`);
      const conf = yamlParse(withSearch["config.yaml"]);
      assert.equal(conf.plugins, undefined, id);
      assert.equal(conf.web, undefined, id);
      continue;
    }
    assert.deepEqual(Object.keys(withSearch).sort(), [...Object.keys(plain), ...PLUGIN_FILES].sort(), id);
    const conf = yamlParse(withSearch["config.yaml"]);
    assert.deepEqual(conf.plugins, { enabled: [HERMES_WEB_SEARCH_PLUGIN] }, id);
    assert.deepEqual(conf.web, { search_backend: HERMES_WEB_SEARCH_BACKEND, extract_backend: HERMES_WEB_SEARCH_BACKEND }, id);
    const want = hermesToolsets({ ...role.descriptor.local_capabilities, web: true });
    for (const p of HERMES_PLATFORMS) assert.deepEqual(conf.platform_toolsets[p], want, `${id} on ${p}`);
    assert.ok(!conf.agent.disabled_toolsets.includes("web"), `${id}: web is not denied`);
    // The rest of the render is untouched.
    assert.equal(withSearch["SOUL.md"], plain["SOUL.md"], id);
    assert.equal(withSearch["profile.yaml"], plain["profile.yaml"], id);
  }
});

test("pm-agent keeps web disabled without web search configured, and gets it with", () => {
  const off = yamlParse(files(renderHermes(getRole("pm-agent")))["config.yaml"]);
  assert.ok(off.agent.disabled_toolsets.includes("web"));
  for (const p of HERMES_PLATFORMS) assert.ok(!off.platform_toolsets[p].includes("web"), p);
  assert.equal(off.plugins, undefined);
  const on = yamlParse(files(renderHermes(getRole("pm-agent"), { webSearch: SEARCH }))["config.yaml"]);
  assert.ok(!on.agent.disabled_toolsets.includes("web"));
  for (const p of HERMES_PLATFORMS) assert.ok(on.platform_toolsets[p].includes("web"), p);
  // A role that does not declare it keeps web disabled even with the gateway configured.
  const coder = yamlParse(files(renderHermes(getRole("code-agent"), { webSearch: SEARCH }))["config.yaml"]);
  assert.ok(coder.agent.disabled_toolsets.includes("web"));
});

// The URL and tool, read back out of the rendered Python the way Python reads it.
function renderedConstants(source) {
  const dir = mkdtempSync(join(tmpdir(), "web-search-94-"));
  roots.push(dir);
  writeFileSync(join(dir, "plugin.py"), source);
  const read = [
    "import ast, json, sys",
    "tree = ast.parse(open(sys.argv[1]).read())",
    "out = {t.id: n.value.value for n in tree.body if isinstance(n, ast.Assign)",
    "       for t in n.targets if isinstance(t, ast.Name) and t.id.startswith('CONFIGURED_')}",
    "print(json.dumps(out))",
  ].join("\n");
  const r = spawnSync("python3", ["-c", read, join(dir, "plugin.py")], { encoding: "utf8" });
  assert.equal(r.status, 0, r.stderr);
  return JSON.parse(r.stdout);
}

test("the plugin is rendered with the user's URL and tool, which can never end the Python literal", () => {
  const [manifest, init] = renderHermesWebSearchPlugin(SEARCH);
  assert.equal(manifest.name, PLUGIN_FILES[0]);
  assert.equal(manifest.content, readFileSync(new URL("../assets/hermes/plugins/web-litellm-search/plugin.yaml", import.meta.url), "utf8"));
  assert.equal(init.name, PLUGIN_FILES[1]);
  assert.equal(init.mode, 0o644);
  assert.doesNotMatch(init.content, /@@LITELLM_SEARCH_(BASE|TOOL)@@/, "no placeholder is left");
  assert.deepEqual(renderedConstants(init.content), { CONFIGURED_BASE: SEARCH.baseUrl, CONFIGURED_TOOL: SEARCH.tool });
  // A URL is validated as a URL, not as a Python string: quotes and backslashes stay data.
  const hostile = 'https://llm.example.com/a"+__import__("os").system("x")+"\\';
  assert.deepEqual(renderedConstants(renderHermesWebSearchPlugin({ baseUrl: hostile, tool: "t" })[1].content),
    { CONFIGURED_BASE: hostile, CONFIGURED_TOOL: "t" });
  // The shipped asset is unrendered: its placeholders are what the plugin reads as "not configured".
  const asset = readFileSync(new URL("../assets/hermes/plugins/web-litellm-search/__init__.py", import.meta.url), "utf8");
  assert.deepEqual(renderedConstants(asset), { CONFIGURED_BASE: "@@LITELLM_SEARCH_BASE@@", CONFIGURED_TOOL: "@@LITELLM_SEARCH_TOOL@@" });
});

test("the plugin cannot be rendered without a gateway URL and a tool", () => {
  for (const bad of [undefined, {}, { baseUrl: SEARCH.baseUrl }, { tool: SEARCH.tool }]) {
    assert.throws(() => renderHermesWebSearchPlugin(bad), /needs a gateway URL and a search tool name/);
  }
});

// ── the plan ────────────────────────────────────────────────────────────────

const ENTRIES = { VBCDX_AGENTS_BASE_DIR: "/b", VBCDX_AGENTS_CREDENTIALS_DIR: "/c", VBCDX_AGENTS_HERMES_HOME: "/h" };
const KEYS = { VBCDX_AGENTS_HERMES_WEB_SEARCH_URL: SEARCH.baseUrl, VBCDX_AGENTS_HERMES_WEB_SEARCH_TOOL: SEARCH.tool };
const plan = (agents, extra = {}) =>
  buildPlan(parseInitArgs(["--harness=hermes", "--env=/c", `--agents=${agents}`, "--dry-run"]), cfg({ ...ENTRIES, ...extra }), { cwd: "/" });

test("the plan writes the plugin into each web-search role's profile, and only there", () => {
  const p = plan("pm-agent,code-agent", KEYS);
  const dests = p.generated.map((g) => g.destination);
  for (const f of PLUGIN_FILES) assert.ok(dests.includes(`/h/profiles/pm-agent/${f}`), f);
  assert.ok(!dests.some((d) => d.startsWith("/h/profiles/code-agent/plugins/")));
  assert.ok(!p.warnings.some((w) => /web search/.test(w)));
});

test("a web-search role with no gateway configured is written without it, and init says so", () => {
  const p = plan("pm-agent,review-agent,code-agent");
  assert.ok(!p.generated.some((g) => g.destination.includes("/plugins/")));
  const w = p.warnings.filter((x) => /web search/.test(x));
  assert.deepEqual(w, ["No Hermes web search configured (VBCDX_AGENTS_HERMES_WEB_SEARCH_URL/_TOOL): pm-agent, review-agent are written without web search."]);
  // No web-search role selected: nothing to warn about.
  assert.ok(!plan("code-agent").warnings.some((x) => /web search/.test(x)));
  // Half a config never reaches the renderer.
  assert.throws(() => plan("pm-agent", { VBCDX_AGENTS_HERMES_WEB_SEARCH_TOOL: SEARCH.tool }), /requires VBCDX_AGENTS_HERMES_WEB_SEARCH_URL/);
});

// ── install, rerun, hand edit, and turning it off ───────────────────────────

function hermesEnv() {
  const root = mkdtempSync(join(tmpdir(), "web-search-94-"));
  roots.push(root);
  const write = (search) => {
    const p = join(root, "config.env");
    const keys = search ? [`VBCDX_AGENTS_HERMES_WEB_SEARCH_URL=${SEARCH.baseUrl}`, `VBCDX_AGENTS_HERMES_WEB_SEARCH_TOOL=${SEARCH.tool}`] : [];
    writeFileSync(p, [`VBCDX_AGENTS_BASE_DIR=${root}/state`, `VBCDX_AGENTS_CREDENTIALS_DIR=${root}/creds`,
      `VBCDX_AGENTS_HERMES_HOME=${root}/hermes`, ...keys].join("\n") + "\n");
    return p;
  };
  return { root, write, profile: (f) => join(root, "hermes", "profiles", "pm-agent", f) };
}
const run = (envFile) => init([PACK_ARG, "--harness=hermes", "--env=" + envFile, "--agents=pm-agent"]);
const actionFor = (report, dest) => report.generated.find((g) => g.destination === dest).action;
const edit = (path, mutate) => { const d = parsePy(readFileSync(path, "utf8")); mutate(d); writeFileSync(path, stringifyPy(d)); };

test("installed web search is owned like the installer's other keys: kept, guarded, and removed when turned off", () => {
  const e = hermesEnv();
  run(e.write(true));
  for (const f of PLUGIN_FILES) assert.ok(existsSync(e.profile(f)), f);
  assert.deepEqual(renderedConstants(readFileSync(e.profile(PLUGIN_FILES[1]), "utf8")),
    { CONFIGURED_BASE: SEARCH.baseUrl, CONFIGURED_TOOL: SEARCH.tool });

  // The operator's own web.* settings are not the installer's, and survive a rerun.
  edit(e.profile("config.yaml"), (d) => { d.web.timeout = 30; });
  assert.equal(actionFor(run(e.write(true)), e.profile("config.yaml")), "noop");

  // A hand edit of an owned web key conflicts instead of being overwritten.
  edit(e.profile("config.yaml"), (d) => { d.web.search_backend = "some-other-backend"; });
  assert.throws(() => run(e.write(true)), (err) => err.code === EXIT.CONFLICT);
  assert.equal(parsePy(readFileSync(e.profile("config.yaml"), "utf8")).web.search_backend, "some-other-backend");
  edit(e.profile("config.yaml"), (d) => { d.web.search_backend = HERMES_WEB_SEARCH_BACKEND; });

  // Turned off: the owned keys go, web is denied again, the operator's key stays.
  assert.equal(actionFor(run(e.write(false)), e.profile("config.yaml")), "update");
  const off = parsePy(readFileSync(e.profile("config.yaml"), "utf8"));
  assert.equal(off.plugins, undefined);
  assert.deepEqual(off.web, { timeout: 30 });
  assert.ok(off.agent.disabled_toolsets.includes("web"));
});
